INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210143, 101086, '36cfff0c-65b8-5120-a6ca-5a6638482165', NULL, 'The disclosure-chilling point is underrated. We already struggle to get companies to report breaches quickly; adding personal ruin to the equation gives every general counsel a reason to slow-walk the forensics. Victims need fast disclosure more than they need a director''s house.', 'agree', 5, '2026-09-23 19:05:24+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210145, 101085, '9636fdba-bd6d-5636-8afc-215db596d82c', NULL, 'I support the principle, but the line-drawing worries me. What counts as a repeat violation: two breaches in five years, or two findings by the same regulator? Without a precise trigger, this becomes a weapon for whichever administration wants to punish a disfavored company.', 'neutral', 5, '2026-09-23 15:42:37+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210146, 101086, '46d72e33-e266-58f6-98b4-f7426a76e81d', NULL, 'The talent-flight argument assumes directors are doing us a favor by serving, but board seats at data-heavy companies pay hundreds of thousands a year for part-time work. If personal accountability scares off candidates, it scares off the ones who were never going to ask hard questions anyway. Good riddance.', 'disagree', 2, '2026-09-23 20:51:24+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210149, 101087, '36cfff0c-65b8-5120-a6ca-5a6638482165', NULL, '18.7 million viewers for the women''s final, more than the men drew. Every executive who says we show what people watch should have to explain that number. The audience is there; the coverage is the lagging indicator, not the leading one.', 'strongly_agree', 5, '2026-09-23 22:12:27+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210151, 101088, '9636fdba-bd6d-5636-8afc-215db596d82c', NULL, 'The platform point is the real story. My daughter has never watched an 11pm highlight show in her life; she follows the WNBA on TikTok and YouTube. Mandating parity on dying formats is fighting the last war. Put the energy into streaming and social, where the actual young audience is.', 'agree', 2, '2026-09-24 00:06:39+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210153, 101087, '2cab12e7-5833-5e5e-9f27-79100b08e8e8', NULL, 'The money argument is strong, but I wonder about cause and effect. Did coverage build the audience, or did stars like Caitlin Clark build the audience that coverage then followed? Probably both, which suggests the answer is stars plus coverage, not coverage alone.', 'neutral', 4, '2026-09-23 20:35:27+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210154, 101088, '0d2002e9-1c82-5dee-8f69-9180da1500b7', NULL, 'Tokenism is a risk, but it is a strange argument against the proposal: any new coverage pattern looks performative at first. The men''s highlights were not born authentic either; they became tradition through repetition. You cannot get to genuine without passing through awkward.', 'disagree', 0, '2026-09-23 23:06:39+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210157, 101089, '9636fdba-bd6d-5636-8afc-215db596d82c', NULL, 'The Academy''s own members are mostly craftspeople, and the show treats them like catering staff. That is not just insulting, it is institutionally insane: you are boring the majority of your own voters. No wonder the ratings are dying; the people who care most are the ones being disrespected.', 'strongly_agree', 4, '2026-09-24 04:36:58+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210159, 101090, '2cab12e7-5833-5e5e-9f27-79100b08e8e8', NULL, 'The ratings collapse from over 43 million to under 20 million is the whole argument. The show is bleeding viewers, and every minute spent on a category the audience does not know is a minute closer to cancellation. The streaming-segment idea is the right compromise: honor the craft properly instead of rushing it at midnight.', 'agree', 2, '2026-09-24 02:47:47+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210161, 101089, 'a1c24624-7d07-5bf6-887f-5a373ba432f3', NULL, 'I am torn. The majority of members point is powerful, but so is the reality that my non-industry friends genuinely do not know what a gaffer does. Maybe the answer is better presentation: a great two-minute package on production design could win over viewers instead of boring them.', 'neutral', 0, '2026-09-24 06:56:58+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210162, 101090, '1db4b8a4-a0d5-5e79-a1a6-bd2aa5d7765e', NULL, 'Ad dollars funding the Academy is precisely the problem: the art institution is hostage to Nielsen. If the Oscars exist to celebrate film, then the celebration should not be edited by advertisers. Take the shorter show, the smaller audience, and keep the integrity of honoring everyone.', 'disagree', 8, '2026-09-24 03:57:47+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210201, 101121, '0b662398-93db-52bd-8f3d-6974900cd4f6', NULL, 'Alamo is the reason I still go to theaters at all. I drive 40 minutes past two multiplexes to get there because I know nobody''s phone will light up. That is the whole business model.', 'agree', 2, '2026-09-23 23:28:16+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210203, 101124, '3b65e3dc-1da2-54bf-9589-9435228a489e', NULL, 'The sitter point is the whole ballgame for me. I am not leaving my phone unreachable for three hours with a six-month-old at home. Phone-free screenings as an option, sure. As the default, you have lost my ticket money.', 'agree', 8, '2026-09-23 21:46:13+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210205, 101125, '4025d5d0-88d0-55e8-817c-79164825f340', NULL, 'Type 1 diabetic here. My glucose alerts go straight to my phone and I am not explaining my pancreas to a teenager with a flashlight. Hard no on default pouches.', 'strongly_agree', 6, '2026-09-24 05:35:37+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210207, 101122, 'd02683a0-27ae-5adc-b36c-da89e6493481', NULL, 'Worked at a theater in college too, and honestly the glow complaints were real but so were the fights. Half the confrontations I saw started because a customer tried to enforce the rule themselves.', 'neutral', 2, '2026-09-24 05:13:16+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210209, 101126, '68098df9-84c5-5727-9f57-9bdf1a2e0371', NULL, 'The box office numbers are the part nobody arguing for this wants to face. Theaters need seats filled, and every added hassle is another reason to wait for streaming.', 'agree', 5, '2026-09-24 03:59:27+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210211, 101127, '8e34d37b-6ceb-55c3-8bc4-1af83a19a23a', NULL, 'Teacher here too. My students have sportsbook apps sitting next to their banking apps. They did not find those on their own; the ads found them during Monday Night Football.', 'agree', 0, '2026-09-24 13:43:48+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210213, 101130, '8553ad35-6355-5c4e-9a5f-9355965ed3ab', NULL, 'The offshore point is underrated. My cousin bets through a site based in Costa Rica with zero limits and zero help resources. The legal market is the only one that answers to anyone.', 'agree', 5, '2026-09-24 13:23:04+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210215, 101132, 'cc1aac53-abf2-559e-8a37-6a6093294ae7', NULL, 'This is pure nanny-state thinking. I read the odds, I set limits, I lose sometimes. That is adulthood. If we banned every ad for something someone might abuse, TV would be blank.', 'strongly_disagree', 1, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210217, 101128, '685e5b74-1b2e-5f08-9dc8-c5fce10e6d17', NULL, 'I do not know where I land. My brother is in recovery and the ads genuinely rattle him, but he also says the apps'' push notifications are ten times worse than anything on TV.', 'neutral', 3, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210219, 101129, '1968764f-9b9b-5968-9771-516f3f5b3ae8', NULL, 'The closed-loop point is sharp. The pregame show quotes the spread, the broadcast runs the ad, the app sponsors the halftime report. At some point it is not coverage, it is a funnel.', 'agree', 8, '2026-09-24 11:43:33+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210220, 101131, '7fb7078b-2cdd-5e48-99b9-3d88509c7812', NULL, '''The money has to come from somewhere'' is right, but the answer cannot be ''so let gambling fund football.'' Pharma ads fund the news too, and we all see how that distorts coverage.', 'disagree', 3, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210221, 101133, '0212097b-9c4d-5391-8547-7b543026d660', NULL, 'ER nurse, four twelves here. The five-day crowd has no idea what a real schedule debate looks like, and they are still the ones setting the default for everyone.', 'strongly_agree', 5, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210223, 101136, '711dc760-ce50-59db-bee6-8b7ffdc7be58', NULL, 'The Friday childcare scramble is exactly what happened in my district. Two hundred families suddenly needing Friday care, and the only winners were the for-profit centers that doubled their rates.', 'agree', 4, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210225, 101137, 'ed5e546e-3d1d-5076-8120-9c937791b507', NULL, 'Restaurant manager here. Every one of these trials is tech and marketing firms. Come run a four-day week on a line cook''s schedule and get back to me.', 'strongly_agree', 4, '2026-09-24 10:35:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210227, 101138, 'cfbc5d47-1a6e-5320-9e59-907fe28564e4', NULL, 'The honest answer is we do not know the long-term effects, and both sides are overstating. Six months of self-reported well-being is not nothing, but it is not settled science either.', 'neutral', 2, '2026-09-24 13:55:42+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210229, 101135, '08ea5a83-927a-5605-96ff-4cc9f9bc87fa', NULL, 'The dishes finding hit home. My wife and I both went four-day during COVID-era pilots and it was the first time the mental load felt close to shared. That alone is worth something.', 'agree', 8, '2026-09-24 12:59:54+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210231, 101139, '451f8cae-d779-51b2-9d96-054e8c5c98ff', NULL, 'Former social media manager here. We literally had a spreadsheet column for ''outrage potential'' when drafting posts. The incentives are exactly as described.', 'agree', 4, '2026-09-23 15:15:14+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210233, 101140, '375c4023-e676-5d4a-8dec-b98c23b99351', NULL, 'Small-town reporter here too. Our boil-water notice got flagged as ''sensitive content'' last year and reach tanked. The filter cannot tell urgency from outrage.', 'agree', 2, '2026-09-23 18:14:48+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210235, 101139, '92fdb777-17c8-5cb7-8bdf-67ff4865b4c5', NULL, 'I keep going back and forth. The rage farms are real, but so is the risk that ''friction'' becomes whatever the platform''s trust and safety team feels like that quarter.', 'neutral', 7, '2026-09-23 17:59:14+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210237, 101140, 'fc03161c-e9f7-5c1f-ad39-dfa213a0b6fe', NULL, 'This is special pleading. Every industry claims a rule will hurt it uniquely. The data on falsehoods outrunning the truth is overwhelming; act on it.', 'strongly_disagree', 1, '2026-09-23 20:55:48+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210239, 101141, '047cbe92-c3ce-55af-8df7-5158dcf2abe9', NULL, 'College junior here. The screen-time audit assignment in my psych class did more for me than four years of adults saying ''put the phone down.'' Practice beats preaching.', 'strongly_agree', 2, '2026-09-23 18:20:48+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210241, 101142, 'd91d5f6f-1a9e-5dfb-97fa-e3a0e5c6cd1a', NULL, 'Teacher here, and the politics point is the one nobody says out loud. Whatever unit we design, half the parents will call it indoctrination and the other half will call it censorship.', 'agree', 6, '2026-09-24 06:11:05+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210243, 101141, '0b662398-93db-52bd-8f3d-6974900cd4f6', NULL, 'I see both sides. My daughter''s school did a decent unit on this, but it was one week in health class competing with everything else. Hard to know how much stuck.', 'neutral', 0, '2026-09-23 16:59:48+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210245, 101142, '3b65e3dc-1da2-54bf-9589-9435228a489e', NULL, 'The ''classroom cannot fix it'' argument could justify never teaching anything hard. Schools teach plenty of things the cafeteria undermines. That is the job.', 'strongly_disagree', 5, '2026-09-24 02:47:05+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210247, 101143, 'd02683a0-27ae-5adc-b36c-da89e6493481', NULL, 'The slot machine line is perfect. I stopped trying to willpower my way past notifications and started charging my phone in the kitchen. Environment beats discipline every time.', 'agree', 5, '2026-09-24 01:47:28+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210249, 101144, '68098df9-84c5-5727-9f57-9bdf1a2e0371', NULL, 'Night-shift nurse, single mom. Our family video call with grandma happens at 10pm because that is when I am home and awake. A ''shared wind-down at ten'' would end the best part of our week.', 'agree', 4, '2026-09-24 00:25:18+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210251, 101143, '459f6151-07cd-5131-9c93-abc4a8b14c09', NULL, 'We are a 9-to-5 family and even we could not hold a full blackout. What worked was one rule: no phones at the dinner table. Small, enforceable, done.', 'neutral', 3, '2026-09-24 01:47:28+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210253, 101144, '86ecb3a7-e7be-5dfb-826b-8ca03c33b037', NULL, 'Honestly the whole premise drips with condescension toward families that do not look like a sitcom. Not everyone gets a synchronized evening, and that is not a failure.', 'strongly_disagree', 8, '2026-09-24 00:36:18+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210255, 101145, '8e34d37b-6ceb-55c3-8bc4-1af83a19a23a', NULL, 'The smoking analogy is the strongest argument here. Nobody thinks a single quitline call ends smoking; it is the accumulation of boring infrastructure. That is exactly what is missing for digital habits.', 'agree', 7, '2026-09-23 14:53:33+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210257, 101146, '8553ad35-6355-5c4e-9a5f-9355965ed3ab', NULL, 'I do intake at a community clinic. We already screen for food insecurity, housing, domestic violence, and depression in fifteen minutes. Adding another screen means doing all of them worse.', 'agree', 1, '2026-09-23 23:37:11+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210259, 101145, 'cc1aac53-abf2-559e-8a37-6a6093294ae7', NULL, 'I like the ambition but worry about the evidence bar. Public health earned its authority with clear outcomes: fewer smokers, fewer deaths. What is the equivalent metric for digital well-being?', 'neutral', 5, '2026-09-23 17:27:33+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210261, 101146, '685e5b74-1b2e-5f08-9dc8-c5fce10e6d17', NULL, 'More bureaucracy is not the answer to a tech problem. The platforms engineered the addiction; making taxpayers fund the cleanup while the profits stay private is backwards.', 'strongly_disagree', 8, '2026-09-23 23:34:11+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210263, 101123, 'b3d1f8fb-6aa7-5a0c-9dc6-c15cf2fa2c11', NULL, 'The compromise framing is exactly right. A default with opt-out screenings means nobody loses anything, and the people who most need quiet finally get it. Theaters already tier screenings by age and format, so this is not some alien concept.', 'strongly_agree', 7, '2026-09-24 03:54:04+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210264, 101123, '486b6fdb-fea2-5050-bdda-391e1e4b1031', NULL, 'I want to agree, but enforcement is where this dies. One glowing screen in a dark theater ruins the scene for fifty people, and ushers will not confront every offender. The policy only works if the consequence is real, like Alamo''s ejection rule.', 'disagree', 7, '2026-09-24 03:26:04+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210266, 101134, 'aa41ea2e-1856-5bfc-9547-d56c2937181a', NULL, 'The hiring point is underrated. In a tight labor market, Fridays off beats a 5% raise for a lot of candidates, and it costs the company nothing in cash. That is a recruiting edge you cannot buy any other way.', 'agree', 2, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210267, 101134, '4a8f4a7e-c9c8-5980-91d6-bb07f645fc75', NULL, 'It worked for a 14-person marketing firm, and I believe them. But the generalizability question is real. The trials keep showing office and knowledge work, and I have yet to see a convincing version for shift work.', 'neutral', 3, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210301, 101181, 'ee7943b4-bcd5-5197-8301-9a00258a076d', NULL, 'The AT&T comparison is the one that convinced me. Long-distance prices fell, new carriers appeared, and nobody today wishes we still had one phone company. Monopoly power in search and app distribution looks exactly like 1982 telecom.', 'strongly_agree', 7, '2026-09-24 13:52:40+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210303, 101184, '7cd5a514-8890-5913-b05b-ec8e5bd9d7ab', NULL, 'The integration argument cuts the other way for me. Gmail, Maps, and Calendar work together because one company built them, and splitting them apart punishes users for a crime the product team did not commit. Fix the conduct, not the company.', 'disagree', 6, '2026-09-24 13:17:33+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210305, 101182, '520fe1cd-e8be-5378-a5e9-ded5b425933e', NULL, 'As someone who ships software for a living, the 30 percent cut is the whole story. I pay Apple nearly a third of my revenue for the privilege of reaching customers on hardware they already bought. No competitive market would sustain that.', 'agree', 3, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210306, 101185, '0ee17e88-9403-554a-b79a-f2caf7e743d8', NULL, 'The China argument is just fear dressed as strategy. American strength never came from protecting monopolies; it came from competition forcing companies to get better. Coddling giants because Beijing exists is how you get lazy giants.', 'strongly_disagree', 5, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210308, 101186, 'ffe71cf0-e68c-5513-8d7f-db5ad04d7846', NULL, 'The IBM case is the cautionary tale I keep coming back to. Thirteen years of litigation and the market solved the problem first. But conduct remedies have their own record of being evaded, so I am genuinely torn.', 'neutral', 5, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210309, 101183, '4d826e95-fcf0-5774-bc28-4bf34075f2c3', NULL, 'Local news is dying in plain sight and the ad-tech monopoly is a big reason why. When one company runs the auction and bids in it, publishers cannot win. Splitting the exchange from the ad business is the minimum honest fix.', 'strongly_agree', 7, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210311, 101187, '4a8f4a7e-c9c8-5980-91d6-bb07f645fc75', NULL, 'The coach salary comparison ends the debate for me. When the head coach makes 10 million and the players who fill the stadium get a stipend, ''amateurism'' is just a word lawyers use to avoid paying labor.', 'strongly_agree', 3, '2026-09-24 11:40:11+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210313, 101190, '3debd55c-ef91-5778-b13e-72a4ca48bd9b', NULL, 'This is my real worry. I swam in college and our program survived on football money. Employee payrolls for 85 scholarship football players would absolutely get non-revenue sports cut, and Title IX cannot conjure money that does not exist.', 'agree', 7, '2026-09-24 11:38:59+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210315, 101188, '38fea548-c1e9-55cb-8386-000018da5b31', NULL, 'The injury angle is everything. I know two former players with chronic pain in their twenties and neither got a dime beyond the surgery. Workers'' comp exists precisely for people hurt doing their job.', 'strongly_agree', 7, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210316, 101191, 'd1e61595-e39e-548a-9fda-cc5c82c37c67', NULL, 'NIL changed the picture more than either side admits. Stars can already earn millions, which was impossible five years ago. Maybe the answer is stronger NIL plus revenue sharing, without reclassifying all 500,000 athletes.', 'neutral', 0, '2026-09-24 13:33:13+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210318, 101189, 'c42de967-cec8-5e1a-a097-c28408dbe53d', NULL, 'The TA analogy does not hold. Teaching assistants do academic work directly tied to the university''s educational mission. Athletics is entertainment attached to a school, which is why the employment question is genuinely harder here.', 'disagree', 7, '2026-09-24 13:49:36+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210320, 101192, '51ff2156-709e-5bbd-aeed-c5e0ae20bb4e', NULL, 'The compliance questions here are the strongest part of the case against. Fifty states, public and private schools, unions, visas, transfers. Whatever the principle, the implementation would be a decade-long mess.', 'neutral', 3, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210321, 101193, 'ea6f2988-62b9-5a2f-832e-de4b2a9ee8c6', NULL, 'The 24 percent heart attack spike is the number that should end this debate. We are talking about a government policy that predictably injures people twice a year. No tradition is worth that.', 'strongly_agree', 8, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
